//! Shared block sound profiles, including integrated content.
use super::{SoundTypeDefinition, EventId};
macro_rules! sound_types {
    ($($variant:ident => ($name:literal, $volume:expr, $pitch:expr, $events:expr)),+ $(,)?) => {
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
        #[repr(u16)]
        pub enum SoundType { $($variant),+ }
        impl SoundType {
            pub fn definition(self) -> &'static SoundTypeDefinition { &super::registry().types[self as usize] }
        }
        pub(super) fn build(find: impl Fn(&str) -> EventId) -> Vec<SoundTypeDefinition> {
            vec![$(SoundTypeDefinition { id: SoundType::$variant, name: $name,
                volume: $volume, pitch: $pitch, events: $events.map(|key| find(key)) }),+]
        }
    };
}
